'use client';

import { useCallback, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from 'react';

export const UPDATE_NOTIFICATION_DEFAULT_INTERVAL = 5 * 60 * 1000;

const useIsomorphicLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

export type UpdateCheckStatus = 'idle' | 'checking' | 'ready' | 'error';
export type UpdateAvailabilityStatus = 'unknown' | 'current' | 'available' | 'dismissed';
export type UpdateCheckReason = 'mount' | 'visibility' | 'interval' | 'configuration' | 'manual';

export type UpdateCheckContext = {
	reason: UpdateCheckReason;
};

export type UpdateDetectedEvent = {
	currentVersion: string;
	latestVersion: string;
	checkedAt: number;
	reason: UpdateCheckReason;
};

export type UpdateNotificationState = {
	checkStatus: UpdateCheckStatus;
	updateStatus: UpdateAvailabilityStatus;
	currentVersion?: string;
	latestVersion?: string;
	checkedAt?: number;
	error?: unknown;
	open: boolean;
};

export type UpdateNotificationController = UpdateNotificationState & {
	check: (reason?: UpdateCheckReason) => Promise<void>;
	dismiss: () => void;
	reopen: () => void;
};

export type UseUpdateNotificationOptions = {
	/** Fetches the deployed version. Pair semantic source changes with sourceKey; callback identity may change freely. */
	getVersion: (context: UpdateCheckContext) => string | undefined | Promise<string | undefined>;
	/** Loaded-page version, captured on first render. When omitted, the first successful check becomes the baseline. */
	currentVersion?: string;
	/** Change this key when the version source changes to invalidate an in-flight check and check the new source. */
	sourceKey?: string | number;
	enabled?: boolean;
	interval?: number | false;
	checkOnMount?: boolean;
	checkOnVisibility?: boolean;
	onUpdate?: (event: UpdateDetectedEvent) => void;
	onError?: (error: unknown) => void;
};

export type ResolveUpdateVersionInput = {
	currentVersion?: string;
	latestVersion: string;
	dismissedVersion?: string;
};

export type ResolvedUpdateVersion = {
	currentVersion: string;
	latestVersion: string;
	updateStatus: Exclude<UpdateAvailabilityStatus, 'unknown'>;
	open: boolean;
};

const initialState: UpdateNotificationState = {
	checkStatus: 'idle',
	updateStatus: 'unknown',
	open: false,
};

type UpdateConfiguration = {
	enabled: boolean;
	generation: number;
	getVersion: UseUpdateNotificationOptions['getVersion'];
	sourceKey?: string | number;
};

type InFlightCheck = {
	generation: number;
	promise: Promise<void>;
};

export function useUpdateNotification({
	getVersion,
	currentVersion,
	sourceKey,
	enabled = true,
	interval = UPDATE_NOTIFICATION_DEFAULT_INTERVAL,
	checkOnMount = true,
	checkOnVisibility = true,
	onUpdate,
	onError,
}: UseUpdateNotificationOptions): UpdateNotificationController {
	const configuredCurrentVersion = currentVersion?.trim() || undefined;
	const [state, setState] = useState<UpdateNotificationState>(() => ({
		...initialState,
		currentVersion: configuredCurrentVersion,
	}));
	const mountedRef = useRef(false);
	const configurationRef = useRef<UpdateConfiguration>({ enabled, generation: 0, getVersion, sourceKey });
	const onUpdateRef = useRef(onUpdate);
	const onErrorRef = useRef(onError);
	const currentVersionRef = useRef<string | undefined>(configuredCurrentVersion);
	const latestVersionRef = useRef<string | undefined>(undefined);
	const dismissedVersionRef = useRef<string | undefined>(undefined);
	const inFlightRef = useRef<InFlightCheck | undefined>(undefined);
	const pendingConfigurationRef = useRef(false);
	const pageVisible = usePageVisibility();

	useIsomorphicLayoutEffect(() => {
		const previous = configurationRef.current;
		const sourceChanged = previous.sourceKey !== sourceKey;
		const configurationChanged = previous.enabled !== enabled || sourceChanged;
		if (sourceChanged) pendingConfigurationRef.current = true;
		configurationRef.current = {
			enabled,
			generation: previous.generation + (configurationChanged ? 1 : 0),
			getVersion,
			sourceKey,
		};
		onUpdateRef.current = onUpdate;
		onErrorRef.current = onError;
		if (configurationChanged) {
			setState((current) => (current.checkStatus === 'checking' ? { ...current, checkStatus: 'idle' } : current));
		}
	}, [enabled, getVersion, onError, onUpdate, sourceKey]);

	useIsomorphicLayoutEffect(() => {
		mountedRef.current = true;
		return () => {
			mountedRef.current = false;
		};
	}, []);

	const check = useCallback(async (reason: UpdateCheckReason = 'manual') => {
		const configuration = configurationRef.current;
		if (!configuration.enabled) return;
		if (inFlightRef.current?.generation === configuration.generation) return inFlightRef.current.promise;

		const isCurrentConfiguration = () =>
			mountedRef.current &&
			configurationRef.current.enabled &&
			configurationRef.current.generation === configuration.generation;
		const run = async () => {
			if (mountedRef.current) {
				setState((current) => ({ ...current, checkStatus: 'checking', error: undefined }));
			}
			try {
				const value = await configuration.getVersion({ reason });
				if (!isCurrentConfiguration()) return;
				const latestVersion = value?.trim();
				const checkedAt = Date.now();
				if (!latestVersion) {
					setState((current) => ({ ...current, checkStatus: 'ready', checkedAt, error: undefined }));
					return;
				}

				const previousLatestVersion = latestVersionRef.current;
				const resolved = resolveUpdateVersion({
					currentVersion: currentVersionRef.current,
					latestVersion,
					dismissedVersion: dismissedVersionRef.current,
				});
				currentVersionRef.current = resolved.currentVersion;
				latestVersionRef.current = latestVersion;
				if (resolved.updateStatus === 'current') dismissedVersionRef.current = undefined;
				setState({ ...resolved, checkStatus: 'ready', checkedAt, error: undefined });

				if (resolved.updateStatus === 'available' && previousLatestVersion !== latestVersion) {
					notifyCallback(
						() => onUpdateRef.current?.({ ...resolved, checkedAt, reason }),
						'[UpdateNotification] onUpdate failed.',
					);
				}
			} catch (error) {
				if (!isCurrentConfiguration()) return;
				setState((current) => ({ ...current, checkStatus: 'error', checkedAt: Date.now(), error }));
				notifyCallback(() => onErrorRef.current?.(error), '[UpdateNotification] onError failed.');
			}
		};

		const promise = run();
		const request = { generation: configuration.generation, promise };
		inFlightRef.current = request;
		try {
			await promise;
		} finally {
			if (inFlightRef.current === request) inFlightRef.current = undefined;
		}
	}, []);

	const dismiss = useCallback(() => {
		const latestVersion = latestVersionRef.current;
		if (!latestVersion || latestVersion === currentVersionRef.current) return;
		dismissedVersionRef.current = latestVersion;
		setState((current) => ({ ...current, updateStatus: 'dismissed', open: false }));
	}, []);

	const reopen = useCallback(() => {
		const latestVersion = latestVersionRef.current;
		if (!latestVersion || latestVersion === currentVersionRef.current) return;
		dismissedVersionRef.current = undefined;
		setState((current) => ({ ...current, updateStatus: 'available', open: true }));
	}, []);

	const autoCheckRef = useRef({ activated: false, enabled: false, visible: pageVisible });
	useEffect(() => {
		const previous = autoCheckRef.current;
		const visible = getPageVisibility();
		let reason: UpdateCheckReason | undefined;
		if (enabled && visible) {
			if (pendingConfigurationRef.current) {
				reason = 'configuration';
			} else if (!previous.activated) {
				if (checkOnMount || (!previous.visible && checkOnVisibility)) {
					reason = previous.visible ? 'mount' : 'visibility';
				}
			} else if (!previous.enabled) {
				if (checkOnMount) reason = 'mount';
			} else if (!previous.visible && checkOnVisibility) {
				reason = 'visibility';
			}
		}
		autoCheckRef.current = {
			activated: previous.activated || (enabled && visible),
			enabled,
			visible,
		};
		if (reason) {
			pendingConfigurationRef.current = false;
			void check(reason);
		}
	}, [check, checkOnMount, checkOnVisibility, enabled, pageVisible, sourceKey]);

	useEffect(() => {
		if (!enabled || !getPageVisibility() || interval === false) return;
		const delay = normalizeInterval(interval);
		if (delay === 0) return;
		const handle = window.setInterval(() => void check('interval'), delay);
		return () => window.clearInterval(handle);
	}, [check, enabled, interval, pageVisible]);

	return { ...state, check, dismiss, reopen };
}

export function resolveUpdateVersion({
	currentVersion,
	latestVersion,
	dismissedVersion,
}: ResolveUpdateVersionInput): ResolvedUpdateVersion {
	const baseline = currentVersion ?? latestVersion;
	if (baseline === latestVersion) {
		return { currentVersion: baseline, latestVersion, updateStatus: 'current', open: false };
	}
	const dismissed = dismissedVersion === latestVersion;
	return {
		currentVersion: baseline,
		latestVersion,
		updateStatus: dismissed ? 'dismissed' : 'available',
		open: !dismissed,
	};
}

function usePageVisibility() {
	return useSyncExternalStore(subscribePageVisibility, getPageVisibility, getServerPageVisibility);
}

function subscribePageVisibility(onStoreChange: () => void) {
	if (typeof document === 'undefined') return () => undefined;
	document.addEventListener('visibilitychange', onStoreChange);
	return () => document.removeEventListener('visibilitychange', onStoreChange);
}

function getPageVisibility() {
	return typeof document === 'undefined' || !document.hidden;
}

function getServerPageVisibility() {
	return true;
}

function normalizeInterval(interval: number) {
	if (!Number.isFinite(interval) || interval <= 0) return 0;
	return Math.max(1000, interval);
}

function notifyCallback(callback: () => void, message: string) {
	try {
		callback();
	} catch (error) {
		console.error(message, error);
	}
}

'use client';

import { ArrowRight, RefreshCw, Rocket, X } from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useEffect, useId, useState } from 'react';
import { createPortal } from 'react-dom';
import type { UpdateNotificationController } from './use-update-notification';

export type UpdateNotificationLabels = {
	title: ReactNode;
	description: ReactNode;
	announcement: string;
	currentVersion: string;
	latestVersion: string;
	refresh: string;
	dismiss: string;
};

export type UpdateNotificationDisplayBaseProps = {
	notification: UpdateNotificationController;
	labels?: Partial<UpdateNotificationLabels>;
	onRefresh?: (notification: UpdateNotificationController) => void;
};

export type UpdateNotificationToastProps = ComponentPropsWithRef<'aside'> & UpdateNotificationDisplayBaseProps;
export type UpdateNotificationBannerProps = ComponentPropsWithRef<'aside'> & UpdateNotificationDisplayBaseProps;
export type UpdateNotificationInlineProps = ComponentPropsWithRef<'section'> & UpdateNotificationDisplayBaseProps;

export const defaultUpdateNotificationLabels: UpdateNotificationLabels = {
	title: '发现新版本',
	description: '新版本已经发布，刷新页面后即可使用。',
	announcement: '发现新版本，请刷新页面。',
	currentVersion: '当前',
	latestVersion: '最新',
	refresh: '立即刷新',
	dismiss: '稍后处理',
};

export function UpdateNotificationToast({
	notification,
	labels: labelOverrides,
	onRefresh,
	className,
	...props
}: UpdateNotificationToastProps) {
	const mounted = useMounted();
	const titleId = useId();
	const labels = { ...defaultUpdateNotificationLabels, ...labelOverrides };
	const announcement = useUpdateAnnouncement(notification, labels);
	if (!mounted) return null;

	return createPortal(
		<>
			<LiveAnnouncement text={announcement} />
			{notification.open && (
				<aside
					{...props}
					aria-labelledby={titleId}
					className={joinClassNames(
						'bg-base-100 text-base-content border-base-300 fixed right-4 bottom-4 z-[80] w-[min(calc(100vw-2rem),24rem)] border p-4 shadow-xl',
						className,
					)}
				>
					<div className='flex items-start gap-3'>
						<div
							className='bg-primary/10 text-primary grid size-9 shrink-0 place-items-center rounded-md'
							aria-hidden='true'
						>
							<Rocket className='size-4' />
						</div>
						<div className='min-w-0 flex-1'>
							<h2 id={titleId} className='pr-7 text-sm font-semibold'>
								{labels.title}
							</h2>
							<div className='text-base-content/70 mt-1 text-sm leading-5'>{labels.description}</div>
							<VersionTransition notification={notification} labels={labels} className='mt-3' />
						</div>
						<DismissButton notification={notification} label={labels.dismiss} className='-mt-1 -mr-1' />
					</div>
					<div className='mt-4 flex justify-end'>
						<RefreshButton notification={notification} label={labels.refresh} onRefresh={onRefresh} />
					</div>
				</aside>
			)}
		</>,
		document.body,
	);
}

export function UpdateNotificationBanner({
	notification,
	labels: labelOverrides,
	onRefresh,
	className,
	...props
}: UpdateNotificationBannerProps) {
	const mounted = useMounted();
	const titleId = useId();
	const labels = { ...defaultUpdateNotificationLabels, ...labelOverrides };
	const announcement = useUpdateAnnouncement(notification, labels);
	if (!mounted) return null;

	return createPortal(
		<>
			<LiveAnnouncement text={announcement} />
			{notification.open && (
				<aside
					{...props}
					aria-labelledby={titleId}
					className={joinClassNames(
						'bg-base-100 text-base-content border-base-300 fixed inset-x-0 top-0 z-[80] border-b shadow-md',
						className,
					)}
				>
					<div className='mx-auto grid max-w-6xl grid-cols-[2.25rem_minmax(0,1fr)_auto] items-center gap-x-3 gap-y-3 px-4 py-3 md:flex md:flex-nowrap md:gap-x-4 md:px-6'>
						<div
							className='bg-primary/10 text-primary col-start-1 row-start-1 grid size-9 shrink-0 place-items-center rounded-md'
							aria-hidden='true'
						>
							<Rocket className='size-4' />
						</div>
						<div className='col-[2/4] row-start-1 min-w-0 flex-1'>
							<h2 id={titleId} className='text-sm font-semibold'>
								{labels.title}
							</h2>
							<div className='text-base-content/70 mt-0.5 text-sm leading-5'>{labels.description}</div>
						</div>
						<VersionTransition notification={notification} labels={labels} className='col-[1/4] row-start-2' />
						<div className='col-[1/4] row-start-3 ml-auto flex items-center gap-1'>
							<RefreshButton notification={notification} label={labels.refresh} onRefresh={onRefresh} />
							<DismissButton notification={notification} label={labels.dismiss} />
						</div>
					</div>
				</aside>
			)}
		</>,
		document.body,
	);
}

export function UpdateNotificationInline({
	notification,
	labels: labelOverrides,
	onRefresh,
	className,
	...props
}: UpdateNotificationInlineProps) {
	const titleId = useId();
	const labels = { ...defaultUpdateNotificationLabels, ...labelOverrides };
	const announcement = useUpdateAnnouncement(notification, labels);

	return (
		<>
			<LiveAnnouncement text={announcement} />
			{notification.open && (
				<section
					{...props}
					aria-labelledby={titleId}
					className={joinClassNames('border-base-300 bg-base-100 text-base-content border-y px-4 py-3', className)}
				>
					<div className='flex flex-wrap items-center gap-x-4 gap-y-3'>
						<div
							className='bg-primary/10 text-primary grid size-9 shrink-0 place-items-center rounded-md'
							aria-hidden='true'
						>
							<Rocket className='size-4' />
						</div>
						<div className='min-w-[12rem] flex-1'>
							<h2 id={titleId} className='text-sm font-semibold'>
								{labels.title}
							</h2>
							<div className='text-base-content/70 mt-0.5 text-sm'>{labels.description}</div>
						</div>
						<VersionTransition notification={notification} labels={labels} />
						<div className='ml-auto flex items-center gap-1'>
							<button type='button' className='btn btn-ghost btn-sm' onClick={notification.dismiss}>
								{labels.dismiss}
							</button>
							<RefreshButton notification={notification} label={labels.refresh} onRefresh={onRefresh} />
						</div>
					</div>
				</section>
			)}
		</>
	);
}

type VersionTransitionProps = {
	notification: UpdateNotificationController;
	labels: UpdateNotificationLabels;
	className?: string;
};

function VersionTransition({ notification, labels, className }: VersionTransitionProps) {
	if (!notification.currentVersion || !notification.latestVersion) return null;
	return (
		<div className={joinClassNames('flex min-w-0 flex-wrap items-center gap-2 text-xs tabular-nums', className)}>
			<span className='flex min-w-0 items-center gap-2'>
				<span className='min-w-0'>
					<span className='text-base-content/70'>{labels.currentVersion}</span>{' '}
					<code className='break-all font-mono'>{notification.currentVersion}</code>
				</span>
				<ArrowRight className='text-base-content/60 size-3.5 shrink-0' aria-hidden='true' />
			</span>
			<span className='min-w-0'>
				<span className='text-base-content/70'>{labels.latestVersion}</span>{' '}
				<code className='text-base-content break-all font-mono font-semibold'>{notification.latestVersion}</code>
			</span>
		</div>
	);
}

type NotificationActionProps = {
	notification: UpdateNotificationController;
	label: string;
	className?: string;
};

function DismissButton({ notification, label, className }: NotificationActionProps) {
	return (
		<button
			type='button'
			className={joinClassNames('btn btn-ghost btn-sm btn-square shrink-0', className)}
			onClick={notification.dismiss}
			aria-label={label}
			title={label}
		>
			<X className='size-4' />
		</button>
	);
}

type RefreshButtonProps = NotificationActionProps & {
	onRefresh?: (notification: UpdateNotificationController) => void;
};

function RefreshButton({ notification, label, onRefresh }: RefreshButtonProps) {
	return (
		<button
			type='button'
			className='btn btn-primary btn-sm shrink-0'
			onClick={() => (onRefresh ?? refreshPage)(notification)}
		>
			<RefreshCw className='size-4' />
			{label}
		</button>
	);
}

function LiveAnnouncement({ text }: { text: string }) {
	return (
		<span className='sr-only' role='status' aria-live='polite' aria-atomic='true'>
			{text}
		</span>
	);
}

function useUpdateAnnouncement(notification: UpdateNotificationController, labels: UpdateNotificationLabels) {
	const [announcement, setAnnouncement] = useState('');
	const message = notification.open
		? [
				labels.announcement,
				notification.currentVersion && `${labels.currentVersion} ${notification.currentVersion}.`,
				notification.latestVersion && `${labels.latestVersion} ${notification.latestVersion}.`,
			]
				.filter(Boolean)
				.join(' ')
		: '';
	useEffect(() => {
		const handle = window.setTimeout(() => setAnnouncement(message), 0);
		return () => window.clearTimeout(handle);
	}, [message]);
	return announcement;
}

function refreshPage() {
	if (typeof window !== 'undefined') window.location.reload();
}

function useMounted() {
	const [mounted, setMounted] = useState(false);
	useEffect(() => setMounted(true), []);
	return mounted;
}

function joinClassNames(...classNames: Array<string | undefined>) {
	return classNames.filter(Boolean).join(' ');
}

'use client';

import type { ReactNode } from 'react';
import {
	UpdateNotificationBanner,
	type UpdateNotificationDisplayBaseProps,
	UpdateNotificationInline,
	UpdateNotificationToast,
} from './update-notification-display';
import {
	type UpdateNotificationController,
	type UseUpdateNotificationOptions,
	useUpdateNotification,
} from './use-update-notification';

export type UpdateNotificationDisplay = 'toast' | 'banner' | 'inline';

export type UpdateNotificationProps = UseUpdateNotificationOptions & {
	display?: UpdateNotificationDisplay;
	labels?: UpdateNotificationDisplayBaseProps['labels'];
	onRefresh?: UpdateNotificationDisplayBaseProps['onRefresh'];
	className?: string;
	render?: (notification: UpdateNotificationController) => ReactNode;
};

export type UpdateNotificationPresenterProps = UpdateNotificationDisplayBaseProps & {
	display?: UpdateNotificationDisplay;
	className?: string;
};

export function UpdateNotification({
	display = 'toast',
	labels,
	onRefresh,
	className,
	render,
	...options
}: UpdateNotificationProps) {
	const notification = useUpdateNotification(options);
	if (render) return render(notification);
	return (
		<UpdateNotificationPresenter
			display={display}
			notification={notification}
			labels={labels}
			onRefresh={onRefresh}
			className={className}
		/>
	);
}

export function UpdateNotificationPresenter({
	display = 'toast',
	notification,
	labels,
	onRefresh,
	className,
}: UpdateNotificationPresenterProps) {
	const props = { notification, labels, onRefresh, className };
	switch (display) {
		case 'banner':
			return <UpdateNotificationBanner {...props} />;
		case 'inline':
			return <UpdateNotificationInline {...props} />;
		default:
			return <UpdateNotificationToast {...props} />;
	}
}
